const root = $input.first().json;
const event = root.body ?? root;
const p = event.payload ?? {};
if (event.event_type !== 'report.daily') throw new Error('Unsupported report event');
if (!event.event_id || !event.tenant_id) throw new Error('Missing event references');
if (p.contains_student_content !== false) throw new Error('Refusing to email a report containing student content');
if (!p.recipient_email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.recipient_email)) throw new Error('No authorized report recipient');
for (const k of ['active_students','open_cases','immediate_cases','overdue_followups']) {
  if (!Number.isInteger(p[k]) || p[k] < 0) throw new Error('Invalid aggregate field: ' + k);
}
const school = String(p.tenant_slug || 'school').slice(0, 80);
const report = `School: ${school}\nActive student accounts: ${p.active_students}\nOpen support cases: ${p.open_cases}\nUrgent open cases: ${p.immediate_cases}\nOverdue follow-ups: ${p.overdue_followups}\nGenerated: ${p.generated_at || 'unknown'}\n\nThese are operational counts, not diagnoses or student rankings. Review cases only in the restricted school dashboard.`;
return [{json:{recipient_email:p.recipient_email, subject:'Saathi daily support operations — '+school, report}}];
